import { relations, sql } from "drizzle-orm";
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";

import { user } from "./auth-schema";

// Better Auth tables live in ./auth-schema.ts (generated by `npx @better-auth/cli generate`).
export * from "./auth-schema";

// All money values are integers in the smallest currency unit (cents), never floats.

const timestamp = (name: string) =>
  integer(name, { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull();

const updatedAt = () =>
  integer("updated_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull();

export const INVOICE_STATUSES = ["draft", "sent", "viewed", "paid", "overdue", "void"] as const;
export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

/** One workspace per user: the business that issues the invoices. */
export const workspace = sqliteTable("workspace", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .unique()
    .references(() => user.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  email: text("email"),
  phone: text("phone"),
  website: text("website"),
  address: text("address"),
  taxId: text("tax_id"),
  /** ISO 4217 code used for new invoices. */
  currency: text("currency").default("USD").notNull(),
  /** Default tax rate in basis points (850 = 8.5%). */
  taxRateBps: integer("tax_rate_bps").default(0).notNull(),
  taxLabel: text("tax_label").default("Tax").notNull(),
  invoicePrefix: text("invoice_prefix").default("INV-").notNull(),
  nextInvoiceNumber: integer("next_invoice_number").default(1).notNull(),
  /** Default payment terms in days. */
  paymentTermsDays: integer("payment_terms_days").default(30).notNull(),
  defaultNotes: text("default_notes"),
  /** Bank details or any text printed under the totals. */
  paymentInstructions: text("payment_instructions"),
  createdAt: timestamp("created_at"),
  updatedAt: updatedAt(),
});

export const client = sqliteTable(
  "client",
  {
    id: text("id").primaryKey(),
    workspaceId: text("workspace_id")
      .notNull()
      .references(() => workspace.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    company: text("company"),
    email: text("email"),
    phone: text("phone"),
    address: text("address"),
    taxId: text("tax_id"),
    notes: text("notes"),
    createdAt: timestamp("created_at"),
    updatedAt: updatedAt(),
  },
  (t) => [index("client_workspace_idx").on(t.workspaceId)],
);

/** Reusable products and services with a default price. */
export const item = sqliteTable(
  "item",
  {
    id: text("id").primaryKey(),
    workspaceId: text("workspace_id")
      .notNull()
      .references(() => workspace.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    description: text("description"),
    unitPrice: integer("unit_price").default(0).notNull(),
    createdAt: timestamp("created_at"),
  },
  (t) => [index("item_workspace_idx").on(t.workspaceId)],
);

export const invoice = sqliteTable(
  "invoice",
  {
    id: text("id").primaryKey(),
    workspaceId: text("workspace_id")
      .notNull()
      .references(() => workspace.id, { onDelete: "cascade" }),
    clientId: text("client_id")
      .notNull()
      .references(() => client.id, { onDelete: "restrict" }),
    /** Human-readable number, unique per workspace (e.g. INV-0042). */
    number: text("number").notNull(),
    status: text("status", { enum: INVOICE_STATUSES }).default("draft").notNull(),
    currency: text("currency").notNull(),
    issueDate: integer("issue_date", { mode: "timestamp_ms" }).notNull(),
    dueDate: integer("due_date", { mode: "timestamp_ms" }).notNull(),
    subtotal: integer("subtotal").default(0).notNull(),
    /** Flat discount in cents, applied before tax. */
    discount: integer("discount").default(0).notNull(),
    taxRateBps: integer("tax_rate_bps").default(0).notNull(),
    taxLabel: text("tax_label").default("Tax").notNull(),
    taxAmount: integer("tax_amount").default(0).notNull(),
    total: integer("total").default(0).notNull(),
    notes: text("notes"),
    paymentInstructions: text("payment_instructions"),
    /** Secret token for the public page /i/[token]. */
    publicToken: text("public_token").notNull().unique(),
    sentAt: integer("sent_at", { mode: "timestamp_ms" }),
    viewedAt: integer("viewed_at", { mode: "timestamp_ms" }),
    paidAt: integer("paid_at", { mode: "timestamp_ms" }),
    createdAt: timestamp("created_at"),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("invoice_workspace_idx").on(t.workspaceId),
    index("invoice_client_idx").on(t.clientId),
    uniqueIndex("invoice_number_unique").on(t.workspaceId, t.number),
  ],
);

export const invoiceLine = sqliteTable(
  "invoice_line",
  {
    id: text("id").primaryKey(),
    invoiceId: text("invoice_id")
      .notNull()
      .references(() => invoice.id, { onDelete: "cascade" }),
    description: text("description").notNull(),
    /** Quantity with 2 decimals stored as integer (150 = 1.50). */
    quantity: integer("quantity").default(100).notNull(),
    unitPrice: integer("unit_price").default(0).notNull(),
    amount: integer("amount").default(0).notNull(),
    position: integer("position").default(0).notNull(),
  },
  (t) => [index("invoice_line_invoice_idx").on(t.invoiceId)],
);

export const workspaceRelations = relations(workspace, ({ one, many }) => ({
  user: one(user, { fields: [workspace.userId], references: [user.id] }),
  clients: many(client),
  invoices: many(invoice),
}));

export const clientRelations = relations(client, ({ one, many }) => ({
  workspace: one(workspace, { fields: [client.workspaceId], references: [workspace.id] }),
  invoices: many(invoice),
}));

export const invoiceRelations = relations(invoice, ({ one, many }) => ({
  workspace: one(workspace, { fields: [invoice.workspaceId], references: [workspace.id] }),
  client: one(client, { fields: [invoice.clientId], references: [client.id] }),
  lines: many(invoiceLine),
}));

export const invoiceLineRelations = relations(invoiceLine, ({ one }) => ({
  invoice: one(invoice, { fields: [invoiceLine.invoiceId], references: [invoice.id] }),
}));
